ALTER TABLE links ADD COLUMN iconMode TEXT NOT NULL DEFAULT 'auto' CHECK(iconMode IN ('auto','manual','none'));
ALTER TABLE links ADD COLUMN iconCheckedAt TEXT;
UPDATE links SET iconMode='manual' WHERE icon<>'';
ALTER TABLE links ADD COLUMN expectedTitle TEXT NOT NULL DEFAULT '';
ALTER TABLE links ADD COLUMN expectedDescription TEXT NOT NULL DEFAULT '';
ALTER TABLE links ADD COLUMN contentStatus TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE links ADD COLUMN similarityScore INTEGER;
ALTER TABLE links ADD COLUMN redirectChain TEXT NOT NULL DEFAULT '[]';
ALTER TABLE health_history ADD COLUMN contentStatus TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE health_history ADD COLUMN similarityScore INTEGER;
ALTER TABLE health_history ADD COLUMN redirectChain TEXT NOT NULL DEFAULT '[]';
ALTER TABLE health_history ADD COLUMN probeUserAgent TEXT;
ALTER TABLE health_history ADD COLUMN probeIntervalSeconds INTEGER;
ALTER TABLE health_history ADD COLUMN probeTimeoutSeconds INTEGER;

